  process.env.PX ??= '0480';         // cell 4.5, 4.5 -- the middle of the room
  process.env.PY ??= '0480';
  process.env.PA ??= '00';           // facing east, so the angel is straight behind
  process.env.ANGAT ??= '3.5,4.5';   // ...one cell west
  process.env.ANGFREEZE ??= '1';
