const EC_SITES = [];
for (let r = 1; r <= 12; r++) { EC_SITES.push([`ecA${r}`, (40 * r) >> 8]); if (r < 12) EC_SITES.push([`ecB${r}`, (40 * (24 - r)) >> 8]); }
